//! Token-program profiles: everything KOB needs to know about a token program, declared in ONE place.
//!
//! KOB pairs with many launchpads (the KRON launchpad, Kasseal, KaspaCom, KForge, ...), each with its own token program or
//! build of a shared one. What differs between those programs is data, and that data lives in `data/programs.json`, one
//! [`ProgramProfile`] per program:
//!
//! | field | what consumes it |
//! |---|---|
//! | `name`, `variant` | the program's [`TemplateId`] (generated by `build.rs`), budget / tip table keys, kob-wasm and web names |
//! | `source`, `template_hash`, `layout` | [`crate::artifacts`]: embedded bytes, template-hash pinning, prefix / state / suffix cut |
//! | `codec` | the state codec family ([`Family`]; [`CodecFamily`] below): state decoding, the order templates of that family |
//! | `owners` | the owner schemes the order templates use for custody and for holders (must be the family's, checked) |
//! | `slots` | token inputs / outputs per transaction: builders, planner, keepers, router intents |
//! | `carrier_floor` | smallest KAS value of a token output the program accepts: builders, order-term checks |
//! | `witness` | how a token input is authorised (signature-script builder variant and its parameters): [`crate::tx`], indexer |
//! | `router_intents` | whether router intents may name the program ([`crate::router::intent_program`]) |
//! | `genesis` | genesis rules: where mint authority can come from, the companion outputs a genesis group may hold ([`crate::registry::verify_genesis`]) |
//! | `record_code` | the executor's persisted one-byte program code (never reused) |
//! | `review` | review status (`reviewed`, `pending-review`, `test-only`) and its basis; equal to the shipped registry's |
//!
//! The compute budgets and keeper tips are measured, not declared: `data/compute_budgets.json`, `data/keeper_tips.json` and
//! `data/pair_keeper_tips.json` are regenerated over every profile (`KOB_REGEN=1`), keyed by `name`.
//!
//! Code is needed only for a new **codec family** (a new state layout or authorisation scheme: a [`CodecFamily`] impl, its
//! order templates and their review) or a new **companion decoder** (a genesis actor whose state bounds the supply). A
//! program of an existing family is data plus review: `kob registry add-program` derives its profile from its bytes
//! ([`derive_profile`]) and `docs/spec/token-programs.md` lists what the reviewer checks.

use std::collections::BTreeSet;
use std::sync::OnceLock;

use serde::{Deserialize, Serialize};
use silverscript_abi::SilAbiArtifact;

use crate::artifacts::TemplateId;
use crate::json::to_hex;
use crate::registry::Family;

/// The profile table this build embeds.
pub const PROGRAMS_JSON: &str = include_str!("../data/programs.json");

/// Schema version of `data/programs.json`.
pub const SCHEMA_VERSION: u32 = 1;

/// `data/programs.json`.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ProfileFile {
    #[serde(rename = "$comment", default, skip_serializing_if = "Option::is_none")]
    pub comment: Option<String>,
    pub schema_version: u32,
    pub programs: Vec<ProgramProfile>,
}

/// Where a program's bytes come from.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum SourceKind {
    /// A `silverc` ABI artifact (one contract; the state span is the artifact's `state_span`).
    SilvercArtifact,
    /// The raw redeem script of one instance (`prefix ‖ state ‖ suffix`), as observed on chain.
    RawRedeem,
}

/// The pinned bytes of a program.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ProgramSource {
    pub kind: SourceKind,
    /// Repo-relative path.
    pub path: String,
    /// Compiler-owned context fields at the head of an artifact's state (Argent `runtime_states` roles), which the KCC-1
    /// actor-type handle fixes in the template prefix (each a `byte[32]` holding the program's own Sil template hash).
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub context_fields: Vec<String>,
}

/// Redeem script cut: `prefix (prefix_len) ‖ state (state_len) ‖ suffix (suffix_len)`.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Layout {
    pub prefix_len: usize,
    pub state_len: usize,
    pub suffix_len: usize,
}

/// Owner values (kcc20: `owner_scheme`; kron: `id_type`) the order templates use.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Owners {
    /// Owner of a token output in order custody (a covenant id).
    pub custody: u8,
    /// Owner of a token output delivered to or held by a wallet key.
    pub holder: u8,
}

/// Token inputs / outputs one transaction of the program may carry (leader included).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Slots {
    pub inputs: usize,
    pub outputs: usize,
}

/// How a token input is authorised: the signature-script builder variant.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum WitnessScheme {
    /// KCC-20 draft ABI: the first token input calls `transfer(next_states, owner_witness)` (leader), every other
    /// `transfer_delegator(owner_witness)` (dispatch tags from the artifact).
    Kcc20Transfer,
    /// KRON columns: `owners | id_types | amounts | is_minters | sigs | witnesses` (one push each, the next states of the
    /// whole covenant group; one witness byte per token input naming its authorising input), then the profile's
    /// `trailing_pushes`, then the redeem script.
    KronColumns,
}

/// [`WitnessScheme`] plus its parameters.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Witness {
    pub scheme: WitnessScheme,
    /// `kron-columns` only: constant pushes after the witness column, before the redeem script (lowercase hex each; `""` is
    /// an empty push, `OP_0`). A program with several entries reads its entry selector there (KForge: `[""]`, selector 0).
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub trailing_pushes: Vec<String>,
}

impl Witness {
    /// The decoded trailing pushes.
    pub fn trailing(&self) -> Vec<Vec<u8>> {
        self.trailing_pushes.iter().map(|h| crate::json::from_hex(h).expect("validated hex")).collect()
    }
}

/// Where a mint authority of the program can come from.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum MinterSource {
    /// Only from the genesis: a genesis without a minter output proves the token never has a live minter (condition C2).
    GenesisOnly,
    /// Not established (e.g. minter lanes behind an extension commitment): live minters must be traced.
    Unknown,
}

/// Role of a companion output in a token's genesis group.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum CompanionRole {
    /// A mint authority (its allowance bounds the supply; needs a decoder).
    Minter,
    /// A zero-amount holder factory.
    Seed,
    /// A bonding curve.
    Curve,
    /// A liquidity pool.
    Pool,
    /// A vault / escrow of the launchpad.
    Vault,
}

impl CompanionRole {
    pub fn as_str(self) -> &'static str {
        match self {
            CompanionRole::Minter => "minter",
            CompanionRole::Seed => "seed",
            CompanionRole::Curve => "curve",
            CompanionRole::Pool => "pool",
            CompanionRole::Vault => "vault",
        }
    }
}

/// A companion covenant output a token's genesis group may hold beside the token's own outputs (a launchpad's minter, seed,
/// curve or pool bound to the token's covenant id). Anything in the group that is neither a token output nor a declared
/// companion is refused (genesis contamination). Companions bound to another covenant id (Kasseal's curve, KForge's rung)
/// are not in the token's group and need no declaration.
///
/// Either `decoder` (a companion whose state KOB reads: the code in [`crate::public_mint`]) or an opaque program given by
/// `template_hash` and its cut (`prefix_len`, `state_len`, `suffix_len`): an instance is recognised by the template hash of
/// its cut, carries no token amount and no mint authority (the reviewer confirms both).
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct CompanionRule {
    pub role: CompanionRole,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub decoder: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub template_hash: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub layout: Option<Layout>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub note: Option<String>,
}

/// Companion decoders this build implements, with the role each decodes.
pub const COMPANION_DECODERS: [(&str, CompanionRole); 2] =
    [("kcc20-public-mint/PublicMint", CompanionRole::Minter), ("kcc20-public-mint/TokenSeed", CompanionRole::Seed)];

impl CompanionRule {
    /// True when `redeem` is an instance of this opaque companion (template hash over its cut).
    pub fn matches_opaque(&self, redeem: &[u8]) -> bool {
        let (Some(h), Some(l)) = (self.template_hash.as_deref().and_then(crate::registry::parse_hex32), self.layout) else {
            return false;
        };
        redeem.len() == l.prefix_len + l.state_len + l.suffix_len
            && silverscript_abi::template_hash(&redeem[..l.prefix_len], &redeem[l.prefix_len + l.state_len..]) == h
    }
}

/// A genesis output recognised as one of a profile's declared companions.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum CompanionMatch {
    /// A companion whose state KOB reads (a decoder of [`COMPANION_DECODERS`]).
    Decoded(crate::public_mint::Companion),
    /// An opaque companion (recognised by its template hash): no amount, no mint authority.
    Opaque(CompanionRole),
}

/// Recognises `redeem` as one of the companions `p` declares (`Ok(None)`: none of them). A decoder's error (an instance of
/// the companion's program whose state is not acceptable, e.g. a wrong template field) is returned as is.
pub fn match_companion(p: &ProgramProfile, redeem: &[u8]) -> Result<Option<CompanionMatch>, String> {
    for rule in &p.genesis.companions {
        match rule.decoder.as_deref() {
            Some(d) => {
                let want_minter = match d {
                    "kcc20-public-mint/PublicMint" => true,
                    "kcc20-public-mint/TokenSeed" => false,
                    other => return Err(format!("unknown companion decoder {other}")),
                };
                if let Some(c) = crate::public_mint::decode_companion(redeem)? {
                    if matches!(c, crate::public_mint::Companion::Minter(_)) == want_minter {
                        return Ok(Some(CompanionMatch::Decoded(c)));
                    }
                }
            }
            None => {
                if rule.matches_opaque(redeem) {
                    return Ok(Some(CompanionMatch::Opaque(rule.role)));
                }
            }
        }
    }
    Ok(None)
}

/// Genesis rules of a program.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct GenesisRules {
    pub minters: MinterSource,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub companions: Vec<CompanionRule>,
}

/// Review status of a program (the shipped registry's `review_status` for a program on it).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum ProgramReview {
    /// Semantic review done; on the strict list of the shipped registry.
    Reviewed,
    /// Pinned, review not done: no token on it is listed.
    PendingReview,
    /// Embedded for tests (prototypes, variants); on no registry.
    TestOnly,
}

/// [`ProgramReview`] and its basis.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Review {
    pub status: ProgramReview,
    pub basis: String,
}

/// Everything KOB needs to know about one token program (see the module docs).
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ProgramProfile {
    /// Program name: the `TemplateId` name (serde), budget / tip table key, kob-wasm program name. `[A-Za-z0-9_]+`.
    pub name: String,
    /// Rust `TemplateId` variant.
    pub variant: String,
    /// Registry template id (`templates[].id` of `registry/tokens.json` when the program is on it).
    pub registry_id: String,
    /// One-byte program code of the executor's record log (persisted: never reused or renumbered).
    pub record_code: u8,
    /// One-line description.
    pub summary: String,
    pub source: ProgramSource,
    /// blake3 template hash over the cut (`template_hash(prefix, suffix)`), lowercase hex.
    pub template_hash: String,
    pub layout: Layout,
    /// State codec family (`kcc20` 112-byte state, `kron` 46-byte state).
    pub codec: Family,
    pub owners: Owners,
    pub slots: Slots,
    /// Smallest KAS value (sompi) of a token output the program accepts (measured in the engine: `c6_diff`).
    pub carrier_floor: u64,
    pub witness: Witness,
    /// Router intents may name the program.
    pub router_intents: bool,
    pub genesis: GenesisRules,
    pub review: Review,
}

// ------------------------------------------------------------------------------------------------ codec families

/// The code behind a profile's `codec`: one implementation per state codec family. It fixes what the family's order
/// templates assume (state length, owner values, witness schemes, the output amount bound) and how a raw redeem script's
/// state is recognised ([`derive_profile`]). A program of an existing family needs no code; a new family is a new impl,
/// its order templates and their review.
pub trait CodecFamily {
    /// The registry family.
    const FAMILY: Family;
    /// State span length.
    const STATE_LEN: usize;
    /// Owner value of order custody (a covenant id).
    const CUSTODY: u8;
    /// Owner value of a wallet holder / maker delivery.
    const HOLDER: u8;
    /// Witness schemes the family's builders implement.
    const WITNESS: &'static [WitnessScheme];
    /// Largest amount one token output may carry (`None`: any positive amount).
    const MAX_OUTPUT_AMOUNT: Option<i64>;
    /// True when `state` is a canonical state span of this family.
    fn is_state(state: &[u8]) -> bool;
}

/// The KCC-20 codec family (draft 112-byte state).
pub struct Kcc20Codec;
/// The KRON codec family (46-byte state).
pub struct KronCodec;

impl CodecFamily for Kcc20Codec {
    const FAMILY: Family = Family::Kcc20;
    const STATE_LEN: usize = 112;
    const CUSTODY: u8 = crate::state::SCHEME_COVID;
    const HOLDER: u8 = crate::state::SCHEME_P2PK;
    const WITNESS: &'static [WitnessScheme] = &[WitnessScheme::Kcc20Transfer];
    const MAX_OUTPUT_AMOUNT: Option<i64> = None;
    fn is_state(state: &[u8]) -> bool {
        // the push opcodes of `amount (8) owner (32) owner_scheme (1) borrow_scheme (1) borrow_guard (32) extension (32)`;
        // structural on purpose: the typed decoder needs the embedded templates, which are being loaded when this runs
        state.len() == Self::STATE_LEN
            && [(0, 0x08), (9, 0x20), (42, 0x01), (44, 0x01), (46, 0x20), (79, 0x20)].iter().all(|&(at, op)| state[at] == op)
    }
}

impl CodecFamily for KronCodec {
    const FAMILY: Family = Family::Kron;
    const STATE_LEN: usize = crate::artifacts::KRON_STATE_LEN;
    const CUSTODY: u8 = crate::family::KRON_TYPE_COVID;
    const HOLDER: u8 = crate::family::KRON_TYPE_ADDR;
    const WITNESS: &'static [WitnessScheme] = &[WitnessScheme::KronColumns];
    const MAX_OUTPUT_AMOUNT: Option<i64> = Some(crate::registry::KRON_MAX_OUTPUT_AMOUNT);
    fn is_state(state: &[u8]) -> bool {
        crate::state::KronState::decode(state).is_ok_and(|s| s.id_type <= 3 && s.is_minter <= 1)
    }
}

/// The constants of a family as values.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct CodecFacts {
    pub family: Family,
    pub state_len: usize,
    pub custody: u8,
    pub holder: u8,
    pub witness: &'static [WitnessScheme],
    pub max_output_amount: Option<i64>,
}

fn facts<C: CodecFamily>() -> CodecFacts {
    CodecFacts {
        family: C::FAMILY,
        state_len: C::STATE_LEN,
        custody: C::CUSTODY,
        holder: C::HOLDER,
        witness: C::WITNESS,
        max_output_amount: C::MAX_OUTPUT_AMOUNT,
    }
}

/// The [`CodecFamily`] constants of `family`.
pub fn codec(family: Family) -> CodecFacts {
    match family {
        Family::Kcc20 => facts::<Kcc20Codec>(),
        Family::Kron => facts::<KronCodec>(),
    }
}

fn codec_is_state(family: Family, state: &[u8]) -> bool {
    match family {
        Family::Kcc20 => Kcc20Codec::is_state(state),
        Family::Kron => KronCodec::is_state(state),
    }
}

// ------------------------------------------------------------------------------------------------ validation

/// Why a profile (or the table) is not acceptable.
#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
#[error("program profile {program}: {message}")]
pub struct ProfileError {
    pub program: String,
    pub message: String,
}

fn perr(p: &str, m: impl Into<String>) -> ProfileError {
    ProfileError { program: p.to_string(), message: m.into() }
}

fn is_hex(s: &str) -> bool {
    s.len().is_multiple_of(2) && s.bytes().all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b))
}

impl ProgramProfile {
    /// The template hash.
    pub fn hash(&self) -> [u8; 32] {
        crate::registry::parse_hex32(&self.template_hash).expect("validated template hash")
    }

    /// The family's constants.
    pub fn codec_facts(&self) -> CodecFacts {
        codec(self.codec)
    }

    /// Structural rules that need no bytes: the fields agree with the codec family and with each other.
    pub fn check_shape(&self) -> Result<(), ProfileError> {
        let e = |m: String| Err(perr(&self.name, m));
        let c = self.codec_facts();
        if self.name.is_empty() || !self.name.chars().all(|ch| ch.is_ascii_alphanumeric() || ch == '_') {
            return e("name must be [A-Za-z0-9_]+".into());
        }
        let id_ok = !self.registry_id.is_empty()
            && self.registry_id.len() <= 64
            && self.registry_id.chars().all(|ch| ch.is_ascii_lowercase() || ch.is_ascii_digit() || ch == '-');
        if !id_ok {
            return e(format!("registry_id `{}` must be 1-64 characters [a-z0-9-]", self.registry_id));
        }
        if self.record_code == 0 {
            return e("record_code 0 is reserved (no program)".into());
        }
        if crate::registry::parse_hex32(&self.template_hash).is_none() {
            return e("template_hash must be 64 lowercase hex characters".into());
        }
        if self.layout.state_len != c.state_len {
            return e(format!(
                "codec {} has a {}-byte state, layout says {}",
                self.codec.as_str(),
                c.state_len,
                self.layout.state_len
            ));
        }
        if self.layout.suffix_len == 0 {
            return e("empty suffix".into());
        }
        if (self.owners.custody, self.owners.holder) != (c.custody, c.holder) {
            return e(format!(
                "owners {{custody {}, holder {}}}: the {} order templates use custody {} and holder {} (a program that cannot hold \
                 those owners needs new order templates)",
                self.owners.custody,
                self.owners.holder,
                self.codec.as_str(),
                c.custody,
                c.holder
            ));
        }
        if self.slots.inputs == 0 || self.slots.outputs == 0 || self.slots.inputs > 127 || self.slots.outputs > 255 {
            return e(format!("slots {}/{} out of range", self.slots.inputs, self.slots.outputs));
        }
        if self.carrier_floor == 0 {
            return e("carrier_floor must be at least 1 sompi".into());
        }
        if !c.witness.contains(&self.witness.scheme) {
            return e(format!("witness scheme {:?} is not one of the {} builders", self.witness.scheme, self.codec.as_str()));
        }
        if self.witness.scheme != WitnessScheme::KronColumns && !self.witness.trailing_pushes.is_empty() {
            return e("trailing_pushes are a kron-columns parameter".into());
        }
        if self.witness.trailing_pushes.iter().any(|h| !is_hex(h) || h.len() > 2 * 75) {
            return e("trailing_pushes must be lowercase hex of at most 75 bytes each".into());
        }
        if !self.source.context_fields.is_empty() && self.source.kind != SourceKind::SilvercArtifact {
            return e("context_fields need a silverc artifact".into());
        }
        if self.source.kind == SourceKind::RawRedeem && self.witness.scheme == WitnessScheme::Kcc20Transfer {
            return e("the kcc20-transfer witness needs the artifact's ABI (dispatch tags): a silverc-artifact source".into());
        }
        for comp in &self.genesis.companions {
            match (&comp.decoder, &comp.template_hash, &comp.layout) {
                (Some(d), None, None) => match COMPANION_DECODERS.iter().find(|(n, _)| n == d) {
                    Some((_, role)) if *role == comp.role => {}
                    Some((_, role)) => {
                        return e(format!("companion decoder {d} decodes a {}, not a {}", role.as_str(), comp.role.as_str()))
                    }
                    None => return e(format!("unknown companion decoder {d} (known: {:?})", COMPANION_DECODERS.map(|d| d.0))),
                },
                (None, Some(h), Some(l)) => {
                    if crate::registry::parse_hex32(h).is_none() || l.suffix_len == 0 {
                        return e("an opaque companion needs a 64-hex template_hash and a non-empty suffix".into());
                    }
                    if comp.role == CompanionRole::Minter {
                        return e("a minter companion needs a decoder (its allowance bounds the supply)".into());
                    }
                }
                _ => return e("a companion is either `decoder` or `template_hash` + `layout`".into()),
            }
        }
        if self.review.basis.trim().is_empty() {
            return e("review.basis is empty".into());
        }
        Ok(())
    }

    /// Checks the profile against the program's bytes (`source`): the layout cut, the template hash and the state span.
    /// Returns the cut (`prefix`, `suffix`) and, for an artifact, the parsed artifact.
    pub fn check_bytes(&self, source: &EmbeddedSource) -> Result<LoadedProgram, ProfileError> {
        let e = |m: String| perr(&self.name, m);
        let loaded = match (self.source.kind, source) {
            (SourceKind::SilvercArtifact, EmbeddedSource::Artifact(json)) => {
                let artifact: SilAbiArtifact = serde_json::from_str(json).map_err(|x| e(format!("artifact json: {x}")))?;
                cut_artifact(&self.name, artifact, &self.source.context_fields)?
            }
            (SourceKind::RawRedeem, EmbeddedSource::Raw(bytes)) => {
                let l = self.layout;
                if bytes.len() != l.prefix_len + l.state_len + l.suffix_len {
                    return Err(e(format!(
                        "raw redeem script is {} bytes, layout {}+{}+{}",
                        bytes.len(),
                        l.prefix_len,
                        l.state_len,
                        l.suffix_len
                    )));
                }
                let prefix = bytes[..l.prefix_len].to_vec();
                let suffix = bytes[l.prefix_len + l.state_len..].to_vec();
                let hash = silverscript_abi::template_hash(&prefix, &suffix);
                LoadedProgram {
                    prefix,
                    state: bytes[l.prefix_len..l.prefix_len + l.state_len].to_vec(),
                    suffix,
                    hash,
                    sil_hash: hash,
                    artifact: None,
                }
            }
            _ => return Err(e(format!("source kind {:?} does not match the embedded bytes", self.source.kind))),
        };
        let got = Layout { prefix_len: loaded.prefix.len(), state_len: loaded.state.len(), suffix_len: loaded.suffix.len() };
        if got != self.layout {
            return Err(e(format!("layout {:?} does not match the bytes ({got:?})", self.layout)));
        }
        if to_hex(&loaded.hash) != self.template_hash {
            return Err(e(format!("template hash {} does not match the bytes ({})", self.template_hash, to_hex(&loaded.hash))));
        }
        if !codec_is_state(self.codec, &loaded.state) {
            return Err(e(format!("the source's state span is not a canonical {} state", self.codec.as_str())));
        }
        if self.witness.scheme == WitnessScheme::Kcc20Transfer {
            let art = loaded.artifact.as_ref().expect("artifact source");
            let entries = &art.contracts.values().next().expect("one contract").entries;
            for (entry, tag) in KCC20_DRAFT_TAGS {
                match entries.get(entry) {
                    Some(x) if x.dispatch_tag.to_hex() == tag => {}
                    Some(x) => {
                        return Err(e(format!(
                            "entry {entry} has dispatch tag {}, the KCC-20 draft's is {tag}",
                            x.dispatch_tag.to_hex()
                        )))
                    }
                    None => return Err(e(format!("kcc20-transfer needs the entry {entry}"))),
                }
            }
        }
        Ok(loaded)
    }
}

/// KCC-20 draft entries and their dispatch tags (what the KCC-20 order templates and builders call).
pub const KCC20_DRAFT_TAGS: [(&str, &str); 2] = [("transfer", "79c71c23"), ("transfer_delegator", "fd3ef14a")];

/// Embedded (or supplied) bytes of a program's source.
#[derive(Clone, Copy, Debug)]
pub enum EmbeddedSource {
    /// A silverc artifact (JSON text).
    Artifact(&'static str),
    /// A raw redeem script.
    Raw(&'static [u8]),
}

/// A program cut by its profile.
#[derive(Clone, Debug)]
pub struct LoadedProgram {
    pub prefix: Vec<u8>,
    /// The source instance's state span.
    pub state: Vec<u8>,
    pub suffix: Vec<u8>,
    /// Template hash of the cut (KOB's, the KCC-1 handle's for a program with context fields).
    pub hash: [u8; 32],
    /// Template hash of the compiler's cut (equal to `hash` without context fields).
    pub sil_hash: [u8; 32],
    pub artifact: Option<SilAbiArtifact>,
}

/// Cuts a silverc artifact: the compiler's state span, with the leading `context` fields moved into the prefix (the KCC-1
/// actor-type handle: each a `byte[32]` whose canonical value `0x20 ‖ sil_hash` is the program's own Sil template hash).
pub fn cut_artifact(name: &str, artifact: SilAbiArtifact, context: &[String]) -> Result<LoadedProgram, ProfileError> {
    let e = |m: String| perr(name, m);
    if artifact.contracts.len() != 1 {
        return Err(e(format!("expected exactly one contract in the artifact, found {}", artifact.contracts.len())));
    }
    let contract = artifact.contracts.values().next().expect("one contract");
    let bytecode = &contract.compiled.bytecode;
    let (offset, len) = (contract.compiled.state_span.offset, contract.compiled.state_span.len);
    if offset + len > bytecode.len() {
        return Err(e(format!("state span {offset}+{len} outside bytecode of {} bytes", bytecode.len())));
    }
    let mut prefix = bytecode[..offset].to_vec();
    let suffix = bytecode[offset + len..].to_vec();
    let sil_hash = silverscript_abi::template_hash(&prefix, &suffix);
    if sil_hash != contract.compiled.template_hash {
        return Err(e(format!(
            "recorded template hash {} != recomputed {}",
            to_hex(&contract.compiled.template_hash),
            to_hex(&sil_hash)
        )));
    }
    let mut at = offset;
    for (k, want) in context.iter().enumerate() {
        let f = contract.runtime_state.fields.get(k).ok_or_else(|| e(format!("no runtime field {k}")))?;
        if &f.name != want || !matches!(f.ty, silverscript_abi::TypeArtifact::FixedBytes { len: 32 }) {
            return Err(e(format!("runtime field {k} is {} ({:?}), not the context field byte[32] {want}", f.name, f.ty)));
        }
        let enc = [&[0x20u8][..], &sil_hash[..]].concat();
        if bytecode.get(at..at + enc.len()) != Some(enc.as_slice()) {
            return Err(e(format!("{want} of the compiled instance is not the canonical 0x20 ‖ {}", to_hex(&sil_hash))));
        }
        prefix.extend_from_slice(&enc);
        at += enc.len();
    }
    let state = bytecode[at..offset + len].to_vec();
    let hash = silverscript_abi::template_hash(&prefix, &suffix);
    Ok(LoadedProgram { prefix, state, suffix, hash, sil_hash, artifact: Some(artifact) })
}

impl ProfileFile {
    /// Parses and checks a profile table (shape of every entry, uniqueness of names, variants, registry ids, record codes
    /// and template hashes). The bytes are checked by [`ProgramProfile::check_bytes`] when a build embeds them.
    pub fn parse(json: &str) -> Result<ProfileFile, ProfileError> {
        let f: ProfileFile = serde_json::from_str(json).map_err(|x| perr("data/programs.json", x.to_string()))?;
        f.check()?;
        Ok(f)
    }

    /// The table rules of [`ProfileFile::parse`].
    pub fn check(&self) -> Result<(), ProfileError> {
        if self.schema_version != SCHEMA_VERSION {
            return Err(perr(
                "data/programs.json",
                format!("schema_version {} (this build reads {SCHEMA_VERSION})", self.schema_version),
            ));
        }
        let mut seen = BTreeSet::new();
        for p in &self.programs {
            p.check_shape()?;
            for key in [
                format!("name {}", p.name),
                format!("variant {}", p.variant),
                format!("registry_id {}", p.registry_id),
                format!("record_code {}", p.record_code),
                format!("template_hash {}", p.template_hash),
            ] {
                if !seen.insert(key.clone()) {
                    return Err(perr(&p.name, format!("duplicate {key}")));
                }
            }
        }
        Ok(())
    }
}

/// The embedded profile table (parsed and shape-checked once; the bytes are checked by [`crate::artifacts::self_check`]).
pub fn table() -> &'static ProfileFile {
    static T: OnceLock<ProfileFile> = OnceLock::new();
    T.get_or_init(|| ProfileFile::parse(PROGRAMS_JSON).unwrap_or_else(|e| panic!("data/programs.json: {e}")))
}

/// Every embedded profile, in table order.
pub fn profiles() -> &'static [ProgramProfile] {
    &table().programs
}

/// The profile of an embedded program by name.
pub fn by_name(name: &str) -> Option<&'static ProgramProfile> {
    profiles().iter().find(|p| p.name == name)
}

/// The profile of an embedded program by registry template id.
pub fn by_registry_id(id: &str) -> Option<&'static ProgramProfile> {
    profiles().iter().find(|p| p.registry_id == id)
}

/// The profile of an embedded program by template hash.
pub fn by_hash(hash: &[u8; 32]) -> Option<&'static ProgramProfile> {
    profiles().iter().find(|p| &p.hash() == hash)
}

/// The profile of a program's record code.
pub fn by_record_code(code: u8) -> Option<&'static ProgramProfile> {
    profiles().iter().find(|p| p.record_code == code)
}

/// The profile of `id` (`None` for an order kind).
pub fn of(id: TemplateId) -> Option<&'static ProgramProfile> {
    by_name(id.name())
}

// ------------------------------------------------------------------------------------------------ derivation

/// What `kob registry add-program` is given.
#[derive(Clone, Debug)]
pub enum ProgramInput {
    /// A silverc artifact (JSON text).
    Artifact(String),
    /// A raw redeem script of one instance (observed on chain).
    Redeem(Vec<u8>),
}

/// Choices the bytes do not decide.
#[derive(Clone, Debug, Default)]
pub struct DeriveOptions {
    pub name: Option<String>,
    pub registry_id: Option<String>,
    pub record_code: Option<u8>,
    pub source_path: Option<String>,
    /// Token inputs / outputs per transaction (measured by the reviewer when the bytes do not say).
    pub slots: Option<Slots>,
    pub summary: Option<String>,
}

/// A derived profile and what the derivation could not establish (each a reviewer task).
#[derive(Clone, Debug, Serialize)]
pub struct Derived {
    pub profile: ProgramProfile,
    /// How the layout was found.
    pub detection: String,
    /// Facts taken from defaults or assumptions: each must be confirmed (or measured) before review.
    pub review_tasks: Vec<String>,
    /// An embedded program with the same template hash, if any (nothing to add then).
    pub already_embedded: Option<String>,
}

/// Derives a profile from a program's bytes: the layout (by detection against the known codec families), the template
/// hash, the codec, the witness scheme and its parameters. What bytes cannot tell (slots, carrier floor, genesis rules,
/// review) is filled with the safe default (`pending-review`, no router intents, `minters: unknown`) and listed in
/// [`Derived::review_tasks`].
pub fn derive_profile(input: &ProgramInput, opt: &DeriveOptions) -> Result<Derived, ProfileError> {
    let label = opt.name.clone().unwrap_or_else(|| "new program".into());
    let e = |m: String| perr(&label, m);
    let mut tasks = vec![];
    let cut = match input {
        ProgramInput::Artifact(json) => {
            let artifact: SilAbiArtifact = serde_json::from_str(json).map_err(|x| e(format!("artifact json: {x}")))?;
            let (cname, contract) = artifact.contracts.iter().next().ok_or_else(|| e("artifact without a contract".into()))?;
            let cname = cname.clone();
            // leading compiler-owned `gen__*` byte[32] fields are context (the KCC-1 handle moves them into the prefix)
            let context: Vec<String> = contract
                .runtime_state
                .fields
                .iter()
                .take_while(|f| f.name.starts_with("gen__") && matches!(f.ty, silverscript_abi::TypeArtifact::FixedBytes { len: 32 }))
                .map(|f| f.name.clone())
                .collect();
            let names: Vec<String> = contract.entries.keys().cloned().collect();
            let has_draft =
                KCC20_DRAFT_TAGS.iter().all(|(n, t)| contract.entries.get(*n).is_some_and(|x| x.dispatch_tag.to_hex() == *t));
            let loaded = cut_artifact(&label, artifact, &context)?;
            let codec = [Family::Kcc20, Family::Kron]
                .into_iter()
                .find(|f| codec_is_state(*f, &loaded.state))
                .ok_or_else(|| e(format!("the {}-byte open state is not a state of a known codec family", loaded.state.len())))?;
            if codec != Family::Kcc20 || !has_draft {
                return Err(e(format!(
                    "a {} state with entries {names:?}: KOB builds artifact calls only for the KCC-20 draft transfer / \
                     transfer_delegator pair; another authorisation scheme is a new witness scheme (code)",
                    codec.as_str()
                )));
            }
            let extra: Vec<&String> = names.iter().filter(|n| !KCC20_DRAFT_TAGS.iter().any(|(d, _)| d == n)).collect();
            if !extra.is_empty() {
                tasks.push(format!(
                    "entries beyond the transfer pair {extra:?}: review what they let an authority do (registry capabilities)"
                ));
            }
            let mut detection = format!(
                "silverc artifact, contract {cname}, open state {} bytes after a {}-byte prefix",
                loaded.state.len(),
                loaded.prefix.len()
            );
            if !context.is_empty() {
                detection.push_str(&format!(", context fields {context:?} moved into the prefix (KCC-1 actor-type handle)"));
            }
            Cut {
                kind: SourceKind::SilvercArtifact,
                codec,
                loaded,
                detection,
                witness: Witness { scheme: WitnessScheme::Kcc20Transfer, trailing_pushes: vec![] },
                context,
            }
        }
        ProgramInput::Redeem(bytes) => {
            let (offset, codec_family) = detect_raw_layout(bytes).ok_or_else(|| {
                e("no state span of a known codec family at offsets 0..=8 (raw scripts: the KRON 46-byte layout; KCC-20 programs are \
                   pinned as artifacts)"
                    .into())
            })?;
            let state_len = codec(codec_family).state_len;
            let prefix = bytes[..offset].to_vec();
            let suffix = bytes[offset + state_len..].to_vec();
            let hash = silverscript_abi::template_hash(&prefix, &suffix);
            let mut trailing = vec![];
            let mut detection =
                format!("raw redeem script of {} bytes: {} state span at offset {offset}", bytes.len(), codec_family.as_str());
            // `OP_TOALTSTACK` before the state, then `OP_FROMALTSTACK OP_DUP 0 OP_NUMEQUAL OP_IF` after it: the last argument is
            // an entry selector whose branch 0 comes first
            if prefix == [0x6b] && suffix.starts_with(&[0x6c, 0x76, 0x00, 0x9c, 0x63]) {
                trailing.push(String::new());
                detection.push_str(
                    "; prefix OP_TOALTSTACK and an `== 0` dispatch on it after the state: an entry selector, trailing push OP_0 \
                     (branch 0)",
                );
                tasks.push(
                    "entry selector: confirm that branch 0 is the owner-authorised transfer of the columns layout, and what every \
                     other branch lets someone do (registry capabilities)"
                        .into(),
                );
            } else if !prefix.is_empty() {
                tasks.push(format!("prefix {}: not a known dispatch pattern; explain it before review", to_hex(&prefix)));
            }
            Cut {
                kind: SourceKind::RawRedeem,
                codec: codec_family,
                loaded: LoadedProgram {
                    state: bytes[offset..offset + state_len].to_vec(),
                    prefix,
                    suffix,
                    hash,
                    sil_hash: hash,
                    artifact: None,
                },
                detection,
                witness: Witness { scheme: WitnessScheme::KronColumns, trailing_pushes: trailing },
                context: vec![],
            }
        }
    };
    let c = codec(cut.codec);
    let name = opt.name.clone().unwrap_or_else(|| format!("Token_{}", &to_hex(&cut.loaded.hash)[..8]));
    let slots = match opt.slots {
        Some(s) => s,
        None => {
            tasks.push("slots: measure the token inputs / outputs one transfer accepts (engine) and pass --slots I/O".into());
            Slots { inputs: 1, outputs: 1 }
        }
    };
    tasks.push("carrier_floor: measure the smallest token output value the program accepts (engine; c6_diff c6_7)".into());
    tasks.push(format!(
        "owners: confirm the program accepts custody owner {} (covenant id) and holder owner {} ({}), which the {} order templates use",
        c.custody,
        c.holder,
        if cut.codec == Family::Kcc20 { "P2PK, token-level signature" } else { "address presence" },
        cut.codec.as_str()
    ));
    if let Some(max) = c.max_output_amount {
        tasks.push(format!("output amounts: confirm the program accepts every amount in 1..={max} (the family's bound)"));
    }
    tasks.push(
        "genesis: decide `minters` (genesis-only needs proof that no transaction creates a minter without spending one) and declare \
         the companion outputs a launch puts in the token's own genesis group (role, template hash, cut)"
            .into(),
    );
    tasks.push("budgets and tips: KOB_REGEN=1 over the budget and tip tables once the program is embedded".into());
    let registry_id = opt.registry_id.clone().unwrap_or_else(|| name.to_ascii_lowercase().replace('_', "-"));
    let record_code = opt.record_code.unwrap_or_else(|| profiles().iter().map(|p| p.record_code).max().unwrap_or(0).saturating_add(1));
    let profile = ProgramProfile {
        variant: variant_of(&name),
        registry_id,
        record_code,
        summary: opt.summary.clone().unwrap_or_else(|| format!("{} token program ({}).", cut.codec.as_str(), cut.detection)),
        source: ProgramSource {
            kind: cut.kind,
            path: opt
                .source_path
                .clone()
                .unwrap_or_else(|| format!("contracts/third-party/{}/{}", name.to_ascii_lowercase(), source_file(cut.kind))),
            context_fields: cut.context,
        },
        template_hash: to_hex(&cut.loaded.hash),
        layout: Layout { prefix_len: cut.loaded.prefix.len(), state_len: cut.loaded.state.len(), suffix_len: cut.loaded.suffix.len() },
        codec: cut.codec,
        owners: Owners { custody: c.custody, holder: c.holder },
        slots,
        carrier_floor: 1,
        witness: cut.witness,
        router_intents: false,
        genesis: GenesisRules { minters: MinterSource::Unknown, companions: vec![] },
        review: Review { status: ProgramReview::PendingReview, basis: "derived by kob registry add-program; not reviewed".into() },
        name,
    };
    profile.check_shape()?;
    let already_embedded = by_hash(&cut.loaded.hash).map(|p| p.name.clone());
    Ok(Derived { profile, detection: cut.detection, review_tasks: tasks, already_embedded })
}

/// A program cut by [`derive_profile`].
struct Cut {
    kind: SourceKind,
    codec: Family,
    loaded: LoadedProgram,
    detection: String,
    witness: Witness,
    context: Vec<String>,
}

fn source_file(kind: SourceKind) -> &'static str {
    match kind {
        SourceKind::SilvercArtifact => "artifact.json",
        SourceKind::RawRedeem => "program.bin",
    }
}

/// UpperCamelCase Rust variant of a program name (`Kforge_Token_1785` -> `KforgeToken1785`).
pub fn variant_of(name: &str) -> String {
    name.split(|c: char| !c.is_ascii_alphanumeric())
        .filter(|s| !s.is_empty())
        .map(|s| {
            let mut c = s.chars();
            c.next().map(|f| f.to_ascii_uppercase().to_string() + c.as_str()).unwrap_or_default()
        })
        .collect()
}

/// Finds a canonical state span of a known codec family in a raw redeem script (offsets 0..=8; KRON layout only: the
/// KCC-20 programs are pinned as artifacts, whose state span the compiler records). The first offset whose span decodes,
/// with a non-empty suffix after it, wins.
pub fn detect_raw_layout(bytes: &[u8]) -> Option<(usize, Family)> {
    let len = KronCodec::STATE_LEN;
    (0..=8usize).find(|&o| bytes.len() > o + len && KronCodec::is_state(&bytes[o..o + len])).map(|o| (o, Family::Kron))
}

/// The registry strict-list entry for a profile (`templates[]` of `registry/tokens.json`), as `kob registry add-program`
/// proposes it: always `pending-review` until the review is done (serialise it with `serde_json::to_string_pretty` to keep
/// the registry's field order).
pub fn registry_template(p: &ProgramProfile, upstream: Option<&str>) -> crate::registry::Template {
    use crate::registry::{Escrow, ReviewStatus, Source, Template};
    let escrow = match p.codec {
        Family::Kcc20 => Escrow { owner_scheme: Some(p.owners.custody), borrow_scheme: Some(0), ..Escrow::default() },
        Family::Kron => Escrow {
            id_type: Some(p.owners.custody),
            is_minter: Some(0),
            delivery_id_type: Some(p.owners.holder),
            ..Escrow::default()
        },
    };
    Template {
        id: p.registry_id.clone(),
        family: p.codec,
        template_hash: p.template_hash.clone(),
        prefix_len: p.layout.prefix_len as u32,
        suffix_len: p.layout.suffix_len as u32,
        state_len: p.layout.state_len as u32,
        max_token_inputs: p.slots.inputs as u32,
        max_token_outputs: p.slots.outputs as u32,
        escrow,
        review_status: ReviewStatus::PendingReview,
        capabilities: vec![],
        risks: vec![],
        source: Source { path: p.source.path.clone(), upstream: upstream.map(str::to_string), note: Some(p.summary.clone()) },
    }
}

// Rules a registry strict-list entry must satisfy when this build embeds its program: the entry's facts are the profile's.
pub fn check_registry_template(t: &crate::registry::Template) -> Result<(), String> {
    let Some(h) = crate::registry::parse_hex32(&t.template_hash) else { return Ok(()) };
    let Some(p) = by_hash(&h) else { return Ok(()) };
    let mut diffs = vec![];
    let mut cmp = |what: &str, a: String, b: String| {
        if a != b {
            diffs.push(format!("{what} {a} (profile {} says {b})", p.name));
        }
    };
    cmp("family", t.family.as_str().into(), p.codec.as_str().into());
    cmp("prefix_len", t.prefix_len.to_string(), p.layout.prefix_len.to_string());
    cmp("state_len", t.state_len.to_string(), p.layout.state_len.to_string());
    cmp("suffix_len", t.suffix_len.to_string(), p.layout.suffix_len.to_string());
    cmp("max_token_inputs", t.max_token_inputs.to_string(), p.slots.inputs.to_string());
    cmp("max_token_outputs", t.max_token_outputs.to_string(), p.slots.outputs.to_string());
    // the custody owner is what the order templates pin; a registry may name either KRON delivery type (0 or 3)
    let custody = match p.codec {
        Family::Kcc20 => t.escrow.owner_scheme,
        Family::Kron => t.escrow.id_type,
    };
    cmp("escrow custody owner", format!("{custody:?}"), format!("{:?}", Some(p.owners.custody)));
    if diffs.is_empty() {
        Ok(())
    } else {
        Err(diffs.join("; "))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_embedded_table_is_valid_and_matches_every_program_byte() {
        let t = table();
        assert_eq!(t.programs.len(), crate::artifacts::TOKEN_PROGRAM_COUNT);
        for p in &t.programs {
            let src = crate::artifacts::embedded_program_source(&p.name).expect("embedded source");
            p.check_bytes(&src).unwrap();
            let id = TemplateId::from_name(&p.name).expect("a TemplateId per profile");
            assert!(id.is_token() && of(id) == Some(p));
            assert_eq!(crate::artifacts::token_template(id).hash, p.hash());
        }
        assert_eq!(TemplateId::TOKEN_PROGRAMS.len(), t.programs.len());
    }

    #[test]
    fn shape_rules_refuse_what_the_order_templates_cannot_serve() {
        let base = by_name("KronToken2433").unwrap().clone();
        let bad = |f: &dyn Fn(&mut ProgramProfile)| {
            let mut p = base.clone();
            f(&mut p);
            p.check_shape().unwrap_err().message
        };
        assert!(bad(&|p| p.owners.holder = 0).contains("order templates use"));
        assert!(bad(&|p| p.layout.state_len = 112).contains("46-byte state"));
        assert!(bad(&|p| p.witness.scheme = WitnessScheme::Kcc20Transfer).contains("not one of the kron builders"));
        assert!(bad(&|p| p.genesis.companions.push(CompanionRule {
            role: CompanionRole::Minter,
            decoder: None,
            template_hash: Some("00".repeat(32)),
            layout: Some(Layout { prefix_len: 0, state_len: 0, suffix_len: 1 }),
            note: None,
        }))
        .contains("needs a decoder"));
        assert!(bad(&|p| p.genesis.companions.push(CompanionRule {
            role: CompanionRole::Seed,
            decoder: Some("kcc20-public-mint/PublicMint".into()),
            template_hash: None,
            layout: None,
            note: None,
        }))
        .contains("decodes a minter"));
        assert!(bad(&|p| p.record_code = 0).contains("reserved"));
        // duplicates across the table
        let mut f = table().clone();
        f.programs.push(ProgramProfile { name: "Other".into(), variant: "Other".into(), ..base.clone() });
        assert!(f.check().unwrap_err().message.contains("duplicate"));
    }

    #[test]
    fn an_embedded_program_derives_its_own_profile() {
        for name in ["KronToken2433", "KCC20Ref_8x8", "KCC20PublicMint", "KCC20KaspaCom_0_2_5"] {
            let p = by_name(name).unwrap();
            let input = match crate::artifacts::embedded_program_source(name).unwrap() {
                EmbeddedSource::Artifact(j) => ProgramInput::Artifact(j.to_string()),
                EmbeddedSource::Raw(b) => ProgramInput::Redeem(b.to_vec()),
            };
            let d = derive_profile(&input, &DeriveOptions { name: Some(name.into()), ..Default::default() }).unwrap();
            assert_eq!(d.already_embedded.as_deref(), Some(name));
            assert_eq!(
                (&d.profile.template_hash, d.profile.layout, d.profile.codec, &d.profile.witness, &d.profile.source.context_fields),
                (&p.template_hash, p.layout, p.codec, &p.witness, &p.source.context_fields),
                "{name}: {}",
                d.detection
            );
            assert_eq!(d.profile.review.status, ProgramReview::PendingReview);
        }
    }

    #[test]
    fn every_registry_template_of_the_shipped_registry_matches_its_profile() {
        let reg = crate::registry::Registry::default_registry();
        for t in &reg.templates {
            let p = by_registry_id(&t.id).unwrap_or_else(|| panic!("registry template {} has no profile", t.id));
            assert_eq!(p.template_hash, t.template_hash, "{}", t.id);
            check_registry_template(t).unwrap();
            let want = match t.review_status {
                crate::registry::ReviewStatus::Reviewed => ProgramReview::Reviewed,
                crate::registry::ReviewStatus::PendingReview => ProgramReview::PendingReview,
            };
            assert_eq!(p.review.status, want, "{}: the profile's review status is the shipped registry's", t.id);
        }
        for p in profiles().iter().filter(|p| p.review.status != ProgramReview::TestOnly) {
            assert!(reg.template(&p.registry_id).is_some(), "{} is {:?} but not on the shipped registry", p.name, p.review.status);
        }
    }

    #[test]
    fn variant_names() {
        assert_eq!(variant_of("KForge_Token_1785"), "KForgeToken1785");
        assert_eq!(variant_of("KCC20Ref_8x8"), "KCC20Ref8x8");
    }
}
